  help_2: 'ଏକ ମୋଟ ବଜେଟ୍ ଓ କିଛି ବର୍ଗର (ଯେପରି ଖାଦ୍ୟ କିମ୍ବା କିଣାକିଣି) ବଜେଟ୍ ରଖନ୍ତୁ। 80%ରେ ସତର୍କ ସୂଚନା ଓ 100% ପାର ହେଲେ ଲାଲ୍ ଆଲର୍ଟ ମିଳିବ।',
  help_3: 'ଭଡ଼ା, EMI, SIP, ସବସ୍କ୍ରିପସନ୍ ଓ ସ୍କୁଲ ଫି “ପ୍ରତି ମାସ” ଟ୍ୟାବରେ ରଖନ୍ତୁ। ଏଗୁଡ଼ିକ ପ୍ରତି ମାସ ସେମାନଙ୍କ ଦିନରେ ଯୋଡ଼ି ହୁଏ; ଆପଣ କେବଳ ଯାଞ୍ଚ କରିବେ।',
  help_4: '50/30/20 ଭାବନା: ଅନେକ ଲୋକ ଆୟର ପ୍ରାୟ 50% ଦରକାର, 30% ସଉକ ଓ 20% ସଞ୍ଚୟ ପାଇଁ ରଖନ୍ତି। ଏହାକୁ ମୋଟାମୋଟି ଦିଗ ଭାବନ୍ତୁ, ପକ୍କା ନିୟମ ନୁହେଁ।',
  help_5: 'ସପ୍ତାହରେ 2 ମିନିଟ୍: ପ୍ରତି ରବିବାର ରିପୋର୍ଟ ଖୋଲନ୍ତୁ, ମୁଖ୍ୟ କଥା ପଢ଼ନ୍ତୁ ଓ ସବୁଠୁ ବଡ଼ ଖର୍ଚ୍ଚ ଦେଖନ୍ତୁ। ଛୋଟ ବଦଳ ମିଶି ବଡ଼ ଫରକ ଆଣେ।',
  help_6: 'ଆପଣଙ୍କ ଡାଟା ଏହି ଡିଭାଇସ ବାହାରକୁ ଯାଏ ନାହିଁ। ନୂଆ ଫୋନକୁ ଯିବାକୁ ବ୍ୟାକଅପ୍ ନେଇ ସେଠାରେ ଫେରାନ୍ତୁ। ବ୍ୟାଙ୍କ କିମ୍ବା UPIର CSV ଷ୍ଟେଟମେଣ୍ଟ ମଧ୍ୟ ଆଣିପାରିବେ।',
