  r_title: '50/30/20 யோசனை',
  r_text: 'ஒரு பொதுவான வழிகாட்டி: வருமானத்தில் சுமார் 50% தேவைகளுக்கு (வாடகை, உணவு, பில்கள்), 30% விருப்பங்களுக்கு, 20% சேமிப்புக்கு. இது தொடக்கம் மட்டுமே; ஒவ்வொரு குடும்பமும் வேறு.',
