  bk_help: 'பேக்கப் கோப்பில் உங்கள் எல்லாப் பதிவுகள், பட்ஜெட்கள், மாதாந்திரப் பதிவுகள் இருக்கும். அதைப் பாதுகாப்பாக வைத்திருங்கள், எ.கா. மின்னஞ்சல் அல்லது Drive இல்.',
