  pp_set_hint: 'இந்த பேக்கப்பைப் பூட்ட ஒரு பாஸ்கோடைத் தேர்ந்தெடுங்கள். அதைப் பாதுகாப்பான இடத்தில் எழுதி வையுங்கள்.',
  pp_open_hint: 'இந்த பேக்கப் பூட்டப்பட்டுள்ளது. அதன் பாஸ்கோடை எழுதுங்கள்.',
