  restore_ok: '{n} பதிவுகள் மீட்டெடுக்கப்பட்டன.',
  imp_title: 'CSV கொண்டு வா',
  imp_help: 'எந்த நெடுவரிசையில் என்ன இருக்கிறது என்று சொல்லுங்கள். CSV ஆகச் சேமித்த பெரும்பாலான வங்கி, UPI அறிக்கைகளும் இந்தச் செயலியின் கோப்புகளும் வேலை செய்யும்.',
  imp_header: 'முதல் வரிசையில் நெடுவரிசைப் பெயர்கள் உள்ளன',
