  imp_dups: 'ஏற்கனவே செயலியில் உள்ள பதிவுகளைத் தவிர்',
  imp_preview: 'முன்னோட்டம்',
  imp_ready: '{n} வரிசைகள் கொண்டு வரத் தயார், {s} வரிசைகளைப் படிக்க முடியவில்லை.',
  imp_err_none: 'எந்த வரிசையையும் படிக்க முடியவில்லை. தேதி, தொகை நெடுவரிசைகளைச் சரிபாருங்கள்.',
  imp_done: '{n} பதிவுகள் வந்தன. {s} தவிர்க்கப்பட்டன.',
  imp_bad: 'இந்தக் கோப்பைப் படிக்க முடியவில்லை.',
  help_1: 'செலவு நடந்தவுடனே பதிவு செய்யுங்கள்: பிரிவைத் தட்டி, தொகையை எழுதி, சேமி தட்டுங்கள். 5 நொடிகள் போதும்; தேதி தானாக இன்றைய தேதி.',
  help_2: 'மொத்த பட்ஜெட்டும் சில பிரிவுகளுக்கு (உணவு, ஷாப்பிங் போல) பட்ஜெட்டும் வையுங்கள். 80% இல் எச்சரிக்கையும் 100% தாண்டினால் சிவப்பு அலர்ட்டும் வரும்.',
  help_3: 'வாடகை, EMI, SIP, சந்தா, பள்ளிக் கட்டணத்தை “மாதந்தோறும்” தாவலில் வையுங்கள். அவை ஒவ்வொரு மாதமும் அவற்றின் நாளில் சேரும்; நீங்கள் சரிபார்த்தால் போதும்.',
  help_4: '50/30/20 யோசனை: பலர் வருமானத்தில் சுமார் 50% தேவைகளுக்கும், 30% விருப்பங்களுக்கும், 20% சேமிப்புக்கும் திட்டமிடுகிறார்கள். இதை ஒரு தோராய வழிகாட்டியாகக் கொள்ளுங்கள், கட்டாய விதியாக அல்ல.',
  help_5: 'வாரம் 2 நிமிடம்: ஒவ்வொரு ஞாயிறும் அறிக்கையைத் திறந்து, முக்கியக் குறிப்புகளைப் படித்து, பெரிய செலவுகளைப் பாருங்கள். சிறு மாற்றங்கள் சேர்ந்து பெரிதாகும்.',
  help_6: 'உங்கள் தரவு இந்தச் சாதனத்தை விட்டு வெளியே போகாது. புதிய ஃபோனுக்கு மாற, பேக்கப் எடுத்து அங்கே மீட்டெடுங்கள். CSV ஆகச் சேமித்த வங்கி அல்லது UPI அறிக்கையையும் கொண்டு வரலாம்.',
  months: 'ஜனவரி,பிப்ரவரி,மார்ச்,ஏப்ரல்,மே,ஜூன்,ஜூலை,ஆகஸ்ட்,செப்டம்பர்,அக்டோபர்,நவம்பர்,டிசம்பர்',
