  help_5: 'ആഴ്ചയിൽ 2 മിനിറ്റ്: എല്ലാ ഞായറാഴ്ചയും റിപ്പോർട്ട് തുറന്ന് പ്രധാന കാര്യങ്ങൾ വായിച്ച് വലിയ ചെലവുകൾ നോക്കുക. ചെറിയ മാറ്റങ്ങൾ ചേർന്ന് വലുതാകും.',
  help_6: 'നിങ്ങളുടെ ഡാറ്റ ഈ ഉപകരണം വിട്ട് പോകില്ല. പുതിയ ഫോണിലേക്ക് മാറാൻ ബാക്കപ്പ് എടുത്ത് അവിടെ തിരികെ കൊണ്ടുവരിക. CSV ആയി സേവ് ചെയ്ത ബാങ്ക് അല്ലെങ്കിൽ UPI സ്റ്റേറ്റ്മെന്റും കൊണ്ടുവരാം.',
